import { RegistryInfo, IRegistryController, DateTimeDecorator, SelectionMode } from "approot/global/components/registry/registry.model";
import { PageContext } from "approot/global/services/context";
import { TaskQueueService } from "approot/global/services/queue/taskqueue.service";
import { QueueExecutionOptions, EnqueueInfo } from "approot/global/services/queue/taskqueue.model";
import { DownloadService } from "approot/global/common.module";
import { DialogsService } from "approot/global/providers/uikit.dialogs";

class EducPortalUploadRegistryController {
	public controller: IRegistryController;
	public registryInfo: RegistryInfo

	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		language,
		private taskQueueService: TaskQueueService,
		private $dialogs: DialogsService,
		private $http: ng.IHttpService,
		private downloadService: DownloadService
	) {

		pageContext.title = "Интеграция с образовательным порталом"
		pageContext.parent = {
			href: "/",
			title: language.Generic.MenuFolders.kDiagnos
		};
		pageContext.back = {
			history: true,
		}

		this.registryInfo = {
			url: "/webapi/admin/educportal/upload/registry",
			filtersUrl: "/webapi/admin/educportal/upload/registry/filter",
			fieldDecorators: {
				"startDate": new DateTimeDecorator(),
				"endDate": new DateTimeDecorator()
			},
			buttons: [
				{ title: "Запустить выгрузку", action: () => this.exportData() },
				{ title: "Загрузить файлы пакетов", action: () => this.downloadPackets(), selectionMode: SelectionMode.Single }
			],
			linkButtons: [],
			export: false,
		}
	}

	downloadPackets() {
		let registryRow = this.controller.selection.items[0];

		let result = registryRow.result;
		if (!result) {
			this.$dialogs.message("Нет информации о файлах выгрузки");
			return
		}
		let uploadResult = <UploadResult>JSON.parse(result);

		if (!uploadResult || !uploadResult.Packets || !uploadResult.Packets.length) {
			return;
		}

		this.$dialogs.confirm("Загрузить " + uploadResult.Packets.length + " файлов?").then(() => {
			for (const packet of uploadResult.Packets) {
				this.downloadService.downloadFile("/webapi/files/" + packet.FileId);
			}
		})
	}

	exportData() {
		let opt: QueueExecutionOptions = {
			header: "Выгрузка информации в образовательный портал",
			logoutputMode: true,
			closeOnEnd: false,
			getTaskFunc: () => {
				return <Promise<EnqueueInfo>>this.$http.post<EnqueueInfo>("/webapi/admin/educportal/upload/queue", null)
					.then((response) => {
						return response.data;
					})
			}
		}
		this.taskQueueService.execute(opt).then(() => {
			this.controller.load();
		});
	}
}

interface UploadResult {
	MessageId: string;
	Organizations: number;
	Message: string;
	Success: boolean;
	Packets: UploadPacketInfo[]
}

interface UploadPacketInfo {
	Number: number;
	FileId: string;
}

export const EducPortalUploadRegistryComponent = {
	template: `<registry info="$ctrl.registryInfo" controller="$ctrl.controller"></registry>`,
	controller: EducPortalUploadRegistryController,
	controllerAs: "$ctrl"
}


