import { RegistryInfo, IRegistryController, PreserveWhiteSpaceDecorator } from "approot/global/components/registry/registry.model";
import { PageContext } from "approot/global/services/context";

class PersonalDataAccessRegistryController {
	public controller: IRegistryController;
	public registryInfo: RegistryInfo

	/*@ngInject*/
	constructor(pageContext: PageContext, language: any) {

		pageContext.title = language.Generic.Secure.kPersonalDataAccess;
		pageContext.parent = {
			href: "/",
			title: language.Generic.MenuFolders.kDiagnos
		};
		pageContext.back = {
			history: true,
		}

		this.registryInfo = {
			url: "/webapi/admin/personalDataAccess/registry",
			filtersUrl: "/webapi/admin/personalDataAccess/registry/filter",
			fieldDecorators: {
				"accessResultInfo": new PreserveWhiteSpaceDecorator()
			},
			buttons: [],
			linkButtons: [],
		}
	}
}

export const PersonalDataAccessRegistryComponent = {
	template: `<registry info="$ctrl.registryInfo"></registry>`,
	controller: PersonalDataAccessRegistryController,
	controllerAs: "$ctrl"
}		


