"use strict";

import { BaseRepository } from "approot/global/repository.js";

export class QueueTaskRepository extends BaseRepository {
	getAll(taskType, status, page, pageSize) {
		const params : any = {};
		if (status) {
			params.status = status;
		}
		if (taskType) {
			params.taskType = taskType;
		}
		if (page || pageSize) {
			params.page = page;
			params.pageSize = pageSize;
		}
		return this.$http.get("/webapi/queueTasks", { params }).then((response) => {
			const tasks = response.data;

			if (response.headers("count")) {
				tasks.totalcount = parseInt(response.headers("count"));
			}

			return tasks;
		});
	}

	delete(ids) {
		return this.$http.delete(`/webapi/queueTasks`, {params: {ids} })
			.then(() => {
				this.$alerts.success("задача успешно удалены");
			})
			.catch(this.handleError);
	}

	retry(ids) {
		return this.$http.get(`/webapi/queueTasks/retry`, {params: {id: ids} })
			.then(() => {
				this.$alerts.success("задача установлена в очередь на повторную обработку");
			})
			.catch(this.handleError);
	}

	clearReportQueue() {
		return this.$http.post(`/webapi/queueTasks/clear`)
			.then((response) => {
				let taskCount = response.data;
				let message = "очередь отчетов успешно очищена";

				if (taskCount > 0) {
					message += `\nудалено ${taskCount} задач`;
				}
				this.$alerts.success(message);
				return response.data;
			})
			.catch(this.handleError);
	}

	getDetails(id) {
		return this.$http.get(`/webapi/queueTasks/${id}`)
			.then((response) => { return response.data; })
			.catch(this.handleError);
	}
}


