import { FilerPanelStyles, PreparedFilterPanelModel, FilterPanelSettings, IFilterPanel } from "../filterpanel/filterpanel.model";
import MultiSelectable from "approot/global/multiSelectable";
import { BehaviorSubject } from "approot/global/models/common.reactive";
declare var dateUtils: any;

export enum SelectionMode {
	"Empty" = "Empty",
	"Multiple" = "Multiple",
	"Single" = "Single"
}

export interface RegistryBtn {
	title: string;
	action: Function;
	selectionMode?: SelectionMode;
	hide?: boolean;
	icon?: string;
	style?: string;

	//свойство только на клиентской стороне. по-хорошему нужно перенести в отдельную viewmodel
	isEnabled?: () => boolean;
}

export interface RegistryBtnGroup {
	title: string;
	icon?: string;
	buttons: RegistryBtn[];
}

export interface Decorator {
	type?: string;
	activate?: (scope: ng.IScope, element: any) => void;
	template?: string;

	//устаревшее, оставлено для обратной совместимости
	action?: (item) => void;
}

export class LinkFieldDecorator implements Decorator {
	public template: string;

	constructor(private linkAction: (item: any) => void) {
		this.template = `<a href="javascript:void(0);" ng-click="action(row, filterInfo)">{{content}}</a>`
	}

	public activate(scope: ng.IScope, element: any) {
		scope["action"] = (row) => {
			this.linkAction(row);
		}
	}
}

export class MapDecorator implements Decorator {
	constructor(private map: (val: string) => string) {
	}

	public activate(scope: ng.IScope, element: any) {
		scope["content"] = this.map(scope["content"]);
	}
}

export class DateDecorator extends MapDecorator {
	constructor(){
		let mapFunc = date => {
			if(!date || date == null || typeof(date) == "undefined"){
				return "";
			}
			let dtDate = new Date(date);
			return dateUtils.date2str(dtDate);
		};
		super(mapFunc) 
	}
}

export class DateTimeDecorator extends MapDecorator {
	constructor(){
		let mapFunc = date => {
			if(!date || date == null || typeof(date) == "undefined"){
				return "";
			}
			let dtDate = new Date(date);
			return dateUtils.date2str(dtDate) + " " + dateUtils.time2Str_ss(dtDate);
		};
		super(mapFunc) 
	}
}

export class PreserveWhiteSpaceDecorator implements Decorator {
	public activate(scope: ng.IScope, element: any) {
		element.css("white-space", "pre-line");
	}
}

export class TextCenterDecorator implements Decorator {
	public activate(scope: ng.IScope, element: any) {
		element.parent().addClass("text-center");
	}
}

export interface IRegistryController {
	load();
	filterInfo: {
		filterPanel: BehaviorSubject<IFilterPanel>;
		filterPanelSettings: FilterPanelSettings;
	};
	selection: MultiSelectable<any>;
	state: IRegistryControllerState;
}

export interface IRegistryControllerState {
	dataReady: boolean;
	loading: boolean;
	emptyData: boolean;
	emptyFilter: boolean;
	selectable: boolean;
	withMultiSelection: boolean;
	exporting: boolean;
	initing: boolean;
}

export interface RegistryInfo {
	//url реестра
	url: string;
	//url инициализации фильтр-панели
	filtersUrl: string;
	buttons?: RegistryBtn[];
	buttonGroups?: RegistryBtnGroup[];
	linkButtons?: RegistryBtn[];
	//переопределения отображения полей
	fieldDecorators?: { [fieldId: string]: Decorator };
	//расширения внешнего вида
	extensions?: {
		//шаблон контента между кнопок и таблицы
		postButtonsTpl: string
	};
	compactFilters?: boolean;

	filtersValues?: any;
	search?: any;

	export?: boolean;
	filterPanelStyles?: FilerPanelStyles;
	registryStyles?: {
		filtersForm?: string;
		table?: string;
	};
	initialPageSize?: number;
}

export interface RegistryRequest {
	filterContext: any;
	fields: string[];

	page: number;
	pageSize: number;

	search?: RegistrySearchInfo;
	order: RegistryOrderInfo;
}

export interface RegistryOrderInfo {
	fieldId: string;
	ascending: boolean;
}

export interface RegistrySearchInfo {
	fieldId: string;
	text: string;
}


export interface RegistryCommandInfo {
	id: string;
	title: string;
	confirm: string;
	mode: any;
	dependencies: any[];

	//свойство только на клиентской стороне. по-хорошему нужно перенести в отдельную viewmodel
	isEnabled?: () => boolean;
}

export interface RegistryDescription {
	fields: RegistryFieldInfo[];
	commands: RegistryCommandInfo[];
	filterPanel: PreparedFilterPanelModel;
	defaultOrder: RegistryOrderInfo;
	autoLoad: boolean;
}

export interface RegistryState {
	paging: PagingInfo | RegistryPagingInfo;
	search: RegistrySearchInfo;
	order: RegistryOrderInfo;
	fields: string[];
}

export interface RegistryResponse {
	rows: any[];
	fields: string[];
	page: number;
	totalItems: number;
}

export interface CommandExecutionResult {
	message: string;
	success: boolean;
	data: any;
	needReload: boolean;
}

export interface RegistryFieldInfo {
	id: string;
	title: string;
	sortable: boolean;

	dependencies: any[];

	order?: number;
	default: boolean;
	search: boolean;
	searchByDefault?: boolean;
}


export interface PagingInfo {
	page: number;
	pageSize: number;
}

export interface RegistryPagingInfo extends PagingInfo {
	currentPageSize: any;
	totalRows: number;
}

export const RegistryBasedComponentTemplate = "<registry info=\"ctrl.registryInfo\" controller=\"ctrl.controller\"></registry>";


