"use strict";

import MultiSelectable from "approot/global/multiSelectable";
import { AppLoader } from "approot/global/apploader";
import { PageContext, AppContext } from "approot/global/services/context";
import { PagingInfo } from "approot/global/components/registry/registry.model";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { QueueTaskRepository } from "./queuetasks.repository";
import { TaskDetailsComponent } from "./details/taskDetails.component";

export class QueueTask {
	public id: number;
	public taskType: string;
	public status: string;
	public enqueueDate: Date;

	public startDate?: Date;
	public endDate?: Date;

	public stalled: boolean;

	constructor(dto) {
		this.id = dto.id;
		this.taskType = dto.taskType;
		this.status = dto.status;

		this.enqueueDate = dto.enqueueDate;
		this.startDate = dto.startDate;
		this.endDate = dto.endDate;
		//this.enqueueDate = moment(dto.enqueueDate).format("YYYY-MM-DD HH:mm:ss");
		//this.startDate = dto.startDate ? moment(dto.startDate).format("YYYY-MM-DD HH:mm:ss") : null;
		//this.endDate = dto.endDate ? moment(dto.endDate).format("YYYY-MM-DD HH:mm:ss") : null;

		this.stalled = dto.stalled;
	}
}

interface TaskPagingInfo extends PagingInfo {
	totalcount: number;
	show: boolean;
}

class QueueTasksController {

	public paging: TaskPagingInfo = {
		page: 1,
		pageSize: 20,
		show: true,
		totalcount: 0
	};

	public data = {
		selection: new MultiSelectable<QueueTask>(),
		refs: {
			taskTypes: [
				{ id: "I", name: "Импорт учащихся" },
				{ id: "E", name: "Экспорт" },
				{ id: "R", name: "Отчет" },
				{ id: "F", name: "Формирование будущего года" }
			],
			taskStatuses: [
				{ id: "Delayed", name: "Отложена" },
				{ id: "InQueue", name: "В очереди" },
				{ id: "Processing", name: "В обработке" },
				{ id: "Error", name: "Ошибка" },
				{ id: "Finished", name: "Завершена" }
			]
		},
		queueTasks: [],
		taskType: "",
		taskStatus: "InQueue"
	}

	public state = {
		dataReady: false,
		dataEmpty: false,
		emptyData: false
	}

	/*@ngInject*/
	constructor(
		private queueTaskRepository : QueueTaskRepository,
		private $appLoader: AppLoader,
		private $longWork: LongWorkService,
		private $dialogs: DialogsService,
		private appContext: AppContext,
		private $uibModal: ng.ui.bootstrap.IModalService,
		public language: any,
		pageContext: PageContext) {

		pageContext.parent = {
			title: language.Generic.MenuFolders.kDiagnos,
			href: `/`
		};
		pageContext.back = { history: true };
		pageContext.title = "Очередь";

		this.load();
	}

	selectAll() {
		this.data.selection.dropSelect();
		for (var task of this.data.queueTasks) {
			this.data.selection.select(task);
		}
	};

	retry(tasks: QueueTask[]) {
		const ids = tasks.map(x => x.id);

		this.$dialogs.confirm(`Вы желаете повторить выбранные задачи?`)
			.then(() => this.queueTaskRepository.retry(ids))
			.then(() => { this.load(); });
	};

	delete(tasks: QueueTask[]) {
		const ids = tasks.map(x => x.id);

		this.$dialogs.confirm(`Вы желаете удалить задачи из БД?`)
			.then(() => this.queueTaskRepository.delete(ids))
			.then(() => { this.load(); });
	};

	clearReportQueue() {
		this.$dialogs.confirm("Вы действительно желаете очистить очередь отчетов?")
			.then(() => {
				this.queueTaskRepository.clearReportQueue();
			});
	}

	viewDetails = (task) => {
		this.queueTaskRepository.getDetails(task.id).then((details) => {

			this.$uibModal.open({
				templateUrl: TaskDetailsComponent.templateUrl,
				controller: TaskDetailsComponent.controller,
				controllerAs: TaskDetailsComponent.controllerAs,
				size: 'lg',
				resolve: {
					queueTaskDetails: details
				}
			});

		});
	};


	testSignalR() {

		let connection = (<any>$).connection.hub;
		let diagHub = (<any>$).connection.diagnosticHub;

		connection.qs = {
			"at": this.appContext.at
		};

		diagHub.client.pong = function (data) {
			console.log("pong");
			alert(data);
			connection.stop();
		};

		connection.start()
			.done(function () {
				console.log("connection started");
				console.log("ping");
				diagHub.server.ping();
			})
			.fail(() => {
				console.log("connection start fail");
				this.$dialogs.error("Ошибка соединения с сервером");
			});
	}

	load() {
		const processing = this.$longWork.show();

		this.queueTaskRepository.getAll(this.data.taskType, this.data.taskStatus, this.paging.page || 1, this.paging.pageSize)
			.then((tasks) => {
				this.paging.totalcount = tasks.totalcount;
				this.paging.show = this.paging.totalcount > this.paging.pageSize && this.paging.page > 0;

				this.data.queueTasks = tasks.map((dto) => new QueueTask(dto));
				this.data.selection.dropSelect();
				this.state.emptyData = !tasks.length;
				this.state.dataReady = true;
				processing.close();

				this.$appLoader.hide();
			});
	};
}

export const QueueTasksComponent = {
	controller: QueueTasksController,
	controllerAs: "$ctrl",
	templateUrl: "/static/dist/app/admin/support/queue/queuetasks.component.html"
}



