import extDeferred from "./extensionDeferred.coffee";

window.isHaveToLogout = true;

export function isDBBusy() {
	return !window.bIsDBFree
}

export function setDBBusy() {
	window.bIsDBFree = false;
}

export function setDBFree() {
	window.bIsDBFree = true;
}

//выполняет проверку наличия изменений. при наличии таковых выводится соответствующее подтверждение
export const checkForChanges = () => extDeferred.when(!window.dataWereChanged || $.show.getConfirmation(language.Generic.Common.kDataWereChanged))

export const GetForm = (fName, obj) => {
	if ($(obj).parents().is('.ui-dialog'))
		return $(obj).parents(".ui-dialog:last").find('form[name=' + fName + ']')[0];
	else
		//### По какой-то причине выбор элементов, без предков .ui-dialog не работает, потому берем первый ###
		return $('form[name=' + fName + ']:first')[0];
}


export const canSubmit = function () {
	return true;
};

export const haveToLogout = function () {
	return window.isHaveToLogout;
};

export const goCommonBack = function () {
	if (typeof Back === "function") {
		return Back();
	} else {
		return goHistoryBack();
	}
};

export const goHistoryBack = function () {
	return checkForChanges().then(function () {
		window.isHaveToLogout = false;
		return history.go(-1);
	});
};

export const DoSubmit = function (form, action) {
	var existToken;
	if (action) {
		form.action = action;
	}
	window.isHaveToLogout = false;
	const createHiddenField = function (form, key, value) {
		const hiddenField = document.createElement("input");
		hiddenField.setAttribute("type", "hidden");
		hiddenField.setAttribute("name", key);
		hiddenField.setAttribute("value", value);
		return form.appendChild(hiddenField);
	};
	existToken = form.at || form.AT;
	if (!existToken) {
		existToken = /\bat\=/i.test(form.action);
	}
	if (!existToken && typeof window.strATTok !== "undefined" && window.strATTok.length) {
		createHiddenField(form, "at", window.strATTok);
	}
	return form.submit();
};

export const goBack = function (form, action) {
	return checkForChanges().then(function () {
		$('input[type="password"]', form).attr("disabled", "disabled");
		return DoSubmit(form, action);
	});
};

export const ok_check_db = function (formName, action) {
	return extDeferred.when(window.bIsDBFree, window.canSubmit).then(function () {
		$(document).trigger("showProcessing");
		setDBBusy();
		return DoSubmit(document.forms[formName], action);
	});
};

export const ok = function (formName, action, obj) {
	var form;
	if (obj === null) {
		form = document.forms[formName];
	} else {
		form = GetForm(formName, obj);
	}
	return extDeferred.when(canSubmit).then(function () {
		return DoSubmit(form, action);
	});
};

export const OnChangeSelect = function (sFormName, sAction) {
	checkForChanges().then(function () {
		return ok_check_db(sFormName, sAction);
	}).fail(function () {
		document.forms[sFormName].reset();
	});
};




