"use strict";

import { AppLoader } from "approot/global/apploader";
import { LongWorkService, DialogsService, IFileDialogOptions } from "approot/global/providers/uikit.dialogs";
import { PageContext } from "approot/global/services/context";
import deferredResLoader from "webroot/static/src/common/js/deferredLoadRes";
import { DoSubmit } from "webroot/static/src/common/js/common.legacy.navigation";
import { SendEmailsComponent } from "./sendEmails/sendEmails.component";
import { QueueExecutionOptions, EnqueueInfo } from "approot/global/services/queue/taskqueue.model";
import { TaskQueueService } from "approot/global/services/queue/taskqueue.service";
import { SettingsProvider, PfdoIntegrationType } from "approot/global/settingsProvider";
import { NamedEntityDto } from "approot/global/models/common.model";

interface BatchImportResult {
	successTasks: number;
	errorsTasks: number;
}

class SupportController {
	public integrationPFDO: boolean = false;
	public pfdoIntegrationType?: PfdoIntegrationType = null;

	constructor(
		public language: any,
		private $appLoader: AppLoader,
		private $longWork: LongWorkService,
		private $dialogs: DialogsService,
		private $location: ng.ILocationService,
		private $uibModal: ng.ui.bootstrap.IModalService,
		private $http: ng.IHttpService,
		private taskQueueService: TaskQueueService,
		private settingsProvider : SettingsProvider,
		pageContext: PageContext) {

		pageContext.parent = null;
		pageContext.back = null;
		pageContext.title = language.Generic.MenuFolders.kDiagnos;

		deferredResLoader.loadJsScript("/vendor/components/signalr/jquery.signalR.min.js");
		deferredResLoader.loadJsScript("/webapi/signalr/hubs");

		this.settingsProvider.ServerSettings.SystemSettings.IntegrationPFDOType().then((integration) => {
			this.pfdoIntegrationType = integration;
			this.integrationPFDO = integration == PfdoIntegrationType.Volgograd;
			this.$appLoader.hide();
		});	
	}

	userDocuments() {
		DoSubmit(document.forms["MenuForm"], "/asp/administration/userDocuments.asp");
	};

	personalDataAccess() {
		this.$location.path("/personaldataaccess/");
	};

	loginAttempts() {
		this.$location.path("/loginattempts/");
	};

	userClones() {
		DoSubmit(document.forms["MenuForm"], "/asp/administration/userClones.asp");
	};

	diagMovement() {
		DoSubmit(document.forms["MenuForm"], "/asp/administration/diagMovement.asp");
	};

	portalUpload() {
		console.log("test")
		this.$location.path("/educportalupload/");
	};

	isIntegration() {
		return this.pfdoIntegrationType == PfdoIntegrationType.IRTechEes || this.pfdoIntegrationType == PfdoIntegrationType.IRTech;
	}

	queueTasks() {
		this.$location.path("/queue/");
	};

	importStudents() {

		const connection = (<any>$).connection.hub;
		const informerHub = (<any>$).connection.progressInformerHub;
		let longWork = null;
		let currentProgress = 0;

		informerHub.client.progress = (data) => {
			currentProgress = (data.Progress / data.Total) * 100;
			if (data.Progress === 1) {
				//закрывается процесссиг от загрузки файла
				$(document).trigger("closeProcessing");
				//отрывается процессинг с прогрессом
				longWork = (<any>$).show.longWork("Выполняется обработка", "Обработка файла пакетного импорта", null, () => currentProgress);
			}
		}

		const prepareControls = this.$http.get<NamedEntityDto[]>("/webapi/globalyears").then((response) => {
			var years = response.data;

			let ftCtrl = (<any>$).uicontrols.select({
				name: "functype",
				items: [
					{ title: "ДОО", value: 1 },
					{ title: "ООО", value: 2 },
					{ title: "ОДО", value: 3 }
				]
			})[0];


			let yearsCtrl = (<any>$).uicontrols.select({
				name: "yearId",
				items: years.map(y => ({ title: y.name, value: y.id }))
			})[0];

			var chooseFuncTypeHtml = '<div class="form-group"><label class="control-label">Тип ОО</label><div>' + ftCtrl.outerHTML + '</div></div>';
			chooseFuncTypeHtml += '<div class="form-group"><label class="control-label">Учебный год</label><div>' + yearsCtrl.outerHTML + '</div></div>';

			return chooseFuncTypeHtml;
		});


		connection.start()
			.fail(() => this.$dialogs.error("Ошибка инициализации comet соединения"))
			.done((res) => {
				prepareControls.then((chooseFuncTypeHtml) => {
					const connectionId = res.id;

					(<any>$).show.fileDialog({
						title: "Импорт учащихся",
						isAjax: true,
						fileExts: [".xls"],
						submitParams: {
							progressId: connectionId
						},
						url: "/webapi/movement/batchimport",
						formAppendContent: chooseFuncTypeHtml,
						handlerAjaxSuccess: function (response) {
							if (longWork) {
								longWork.close();
							}
							if (response.IsError) {
								this.$dialogs.error(response.data.message);
								return;
							}
							var message = `успешно установлено ${response.successTasks} задачи в импорт`;
							if (response.errorTasks) {
								message += `\nошибок: ${response.errorTasks}`;
							}
							alert(message);
						}
					});
				});
			});
	};

	importStaff() {
		let dialogOptions: IFileDialogOptions = {
			url: "/webapi/users/staff/batchimport",
			fileExts: [".csv"]
		}

		return this.$dialogs.uploadFile<BatchImportResult>("Импорт сотрудников", dialogOptions)
			.then((response) => {
				let res = response.result;
				if ((<any>res).IsError) {
					this.$dialogs.error((<any>res).message);
					return;
				}
				let message = `успешно импортировано ${res.successTasks}`;
				if (res.errorsTasks) {
					message += `\nошибок: ${res.errorsTasks}`;
				}
				this.$dialogs.message(message);
				return res;
			})
	};

	//признак - просмотр локального сайта
	isLocalHostView() {
		return location.host.includes("localhost");
	}

	setStaffPasswords() {
		this.$dialogs.confirm("Пароли всех сотрудников с заполненным EMAL будут изменены.\r\nПродолжить?")
			.then(() => {
				const processing = this.$longWork.show();
				this.$http.post("/webapi/users/staff/passwords", null)
					.then(() => {
						processing.close();
						alert("Пароли успешно установлены");
					},
						() => { processing.close(); });
			});
	}

	sendEmail() {
		this.$uibModal.open({
			templateUrl: SendEmailsComponent.templateUrl,
			controller: SendEmailsComponent.controller,
			controllerAs: SendEmailsComponent.controllerAs,
			resolve: {}
		});
	}

	getPfdoAddPrograms() {
		if (!this.integrationPFDO) {
			return;
		}

		let opt: QueueExecutionOptions = {
			header: "Получение программ доп.образования из АИС ПФДО",
			logoutputMode: true,
			closeOnEnd: false,
			getTaskFunc: () => {
				return <Promise<EnqueueInfo>>this.$http.post<EnqueueInfo>("/webapi/integration/pfdo/syncaddprograms", null)
					.then((response) => {
						return response.data;
					})
			}
		}
		this.taskQueueService.execute(opt);
	}

	uploadPfdoCertificates() {
		if (!this.integrationPFDO) {
			return;
		}

		let opt: QueueExecutionOptions = {
			header: "Выгрузка сертификатов в АИС ПФДО",
			logoutputMode: true,
			closeOnEnd: false,
			getTaskFunc: () => {
				return <Promise<EnqueueInfo>>this.$http.post<EnqueueInfo>("/webapi/integration/pfdo/uploadPfdoCertificates", null)
					.then((response) => {
						return response.data;
					})
			}
		}

		this.taskQueueService.execute(opt);
	}

	syncPfdoCertificateGroups() {
		if (!this.integrationPFDO) {
			return;
		}

		let opt: QueueExecutionOptions = {
			header: "Получение категории сертификатов из АИС ПФДО",
			logoutputMode: true,
			closeOnEnd: false,
			getTaskFunc: () => {
				return <Promise<EnqueueInfo>>this.$http.post<EnqueueInfo>("/webapi/integration/pfdo/syncPfdoCertificateGroups", null)
					.then((response) => {
						return response.data;
					})
			}
		}

		this.taskQueueService.execute(opt);
	}

	

}

export const SupportComponent = {
	controller: SupportController,
	controllerAs: "$ctrl",
	templateUrl: "/static/dist/app/admin/support/support.component.html"
}



