import { ResourceLoader } from "./resourceLoader.js";

const deferredResLoader = (function() {
	//define resource to load
	const scriptsToLoad = [];
	const stylesToLoad = ["/static/dist/common/css/ext-styles.min.css"];

	const _allScriptLoadedDefer = $.Deferred();
	const _allScriptLoadedPromise = _allScriptLoadedDefer.promise();

	const _resourceLoader = new ResourceLoader(window.getVersionedLink);

	let scriptsAlreadyLoaded = 0;

	//базовый обработчик загрузки скрипта
	const _baseLoadHandler = function(src) { 
		scriptsAlreadyLoaded = scriptsAlreadyLoaded + 1;
		//console.log "loaded script -- #{src}. #{scriptsAlreadyLoaded}"
		if (scriptsAlreadyLoaded === scriptsToLoad.length) {
			return _allScriptLoadedDefer.resolve();
		}
	};
	
	//функция возвращающая прокси для внешнего обработчика
	const _proxyLoadHandler = handler =>
		function(src) {
			if (handler) { handler(src); }
			return _baseLoadHandler(src);
		}
	;

	//attach on window load event - deferred loading resources
	const loadHandler = function() {
		let src;
		const extScriptsFile = (typeof appContext !== 'undefined' && appContext !== null ? appContext.environment : undefined) === "dev" ? "/static/dist/common/js/ext-scripts.js" : "/static/dist/common/js/ext-scripts.min.js";
		scriptsToLoad.push({src: extScriptsFile});
		for (src of stylesToLoad) {
			_resourceLoader.loadStyleSheet(src);
		}

		for (let info of scriptsToLoad) {
			info.handler = _proxyLoadHandler(info.handler);
			_resourceLoader.loadScript(info.src, info.handler);
		}
	};

	if (window.addEventListener) {
		window.addEventListener("load", loadHandler, false);
	} else if (window.attachEvent) {
		window.attachEvent("onload", loadHandler);
	} else { window.onload = loadHandler; }
	
	//public methods
	return {
		loadScript(src, onScriptLoadHandler) {
			return scriptsToLoad.push({src, handler: onScriptLoadHandler});
		},
		loadStyle(src) {
			return stylesToLoad.push(src);
		},
		loadJsScript(src, onScriptLoadHandler) { 
			return _resourceLoader.loadScript(src, onScriptLoadHandler);
		},
		ready(handler) {
			return _allScriptLoadedPromise.then(handler);
		},
		promise() { return _allScriptLoadedPromise; }
	};
})();

export default deferredResLoader;


