class SendEmailsController {
	public header: string;
	public email = {
		message: "",
		subject: ""
	}

	/*@ngInject*/
	constructor(
		private $uibModalInstance: ng.ui.bootstrap.IModalInstanceService,
		private $http: ng.IHttpService,
		public language
		) {

		this.header = "Отправка сообщений сотрудникам";
	}

	send() {
		let data = {
			subject: this.email.subject,
			message: this.email.message
		};

		$(document).trigger("showProcessing");

		this.$http.post("/webapi/users/staff/email/send", data).then(
			() => {
				$(document).trigger("closeProcessing");
				alert("Сообщение отправлено успешно");
				this.$uibModalInstance.close();
			},
			() => {
				$(document).trigger("closeProcessing");
			});
	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel");
	};
}

export const SendEmailsComponent = {
	controller: SendEmailsController,
	controllerAs: "$ctrl",
	templateUrl: "/static/dist/app/admin/support/sendEmails/sendEmails.component.html"
}





