//angular = require 'angular'
declare var angular: ng.IAngularStatic;

const module = angular.module("irtech.netcity.admin.support",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components",
		"irtech.netcity.directive"
	]);

require("approot/global/directives/storageDirective.coffee");

import { SupportComponent } from "./support.component";
import { QueueTasksComponent } from "./queue/queuetasks.component";
import { EducPortalUploadRegistryComponent } from "./educPortalUpload/educPortalUpload.registry.component";
import { LoginAttemptsRegistryComponent } from "./loginAttempts/loginAttempts.registry.component";
import { PersonalDataAccessRegistryComponent } from "./personalDataAccess/personalDataAccess.registry.component";
import { QueueTaskRepository } from "./queue/queuetasks.repository";

module
	.service("queueTaskRepository", QueueTaskRepository)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/", SupportComponent)
			.when("/queue/", QueueTasksComponent)
			.when("/personaldataaccess/", PersonalDataAccessRegistryComponent)
			.when("/educportalupload/", EducPortalUploadRegistryComponent)
			.when("/loginattempts/", LoginAttemptsRegistryComponent);

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



