import { RegistryInfo, IRegistryController } from "approot/global/components/registry/registry.model";
import { PageContext } from "approot/global/services/context";

class LoginAttemptsRegistryController {
	public controller: IRegistryController;
	public registryInfo: RegistryInfo

	/*@ngInject*/
	constructor(pageContext: PageContext, language: any) {

		pageContext.title = language.Generic.ServAdmin.kLogins
		pageContext.parent = {
			href: "/",
			title: language.Generic.MenuFolders.kDiagnos
		};
		pageContext.back = {
			history: true,
		}

		this.registryInfo = {
			url: "/webapi/admin/loginAttempts/registry",
			filtersUrl: "/webapi/admin/loginAttempts/registry/filter",
			buttons: [],
			linkButtons: [],
		}
	}
}

export const LoginAttemptsRegistryComponent = {
	template: `<registry info="$ctrl.registryInfo"></registry>`,
	controller: LoginAttemptsRegistryController,
	controllerAs: "$ctrl"
}



